  function persist() { try { localStorage.setItem('keiro', JSON.stringify(C)); } catch (e) {} }
  const live = () => !!(C.url && C.pin);
  const base = () => { let u = (C.url || '').trim().replace(/\/+$/, ''); if (u && !/^https?:\/\//i.test(u)) u = 'https://' + u; return u; };
  const media = p => !p ? '' : /^https?:|^data:|^blob:/i.test(p) ? p : base() + (p[0] === '/' ? '' : '/') + p;

  /* demo frames: drawn placeholders (night city + facecam box + caption), no real footage */
  const DEMO_T = {"k412": "data:image/svg+xml;base64,", "k413": "data:image/svg+xml;base64,", "k414": "data:image/svg+xml;base64,", "k398": "data:image/svg+xml;base64,", "k399": "data:image/svg+xml;base64,"};
  /* ---------- demo feed (the brief, section 4) ---------- */
